using Bank.Payments.Domain.Port;
using Bank.Payments.Infrastructure;

namespace Bank.Payments.Adapters.Out.Sql;

/// <summary>
/// Replaces the legacy procedure db_cuentas..sp_debito against the migrated ct_cuenta, inside the
/// transaction of the request. The approved rules do not describe sp_debito, and the schema has no
/// movement table. This adapter therefore only subtracts the amount from the balance, and any case where
/// it cannot do that is raised as an exception, which the use case maps to DEBIT_FAILED or
/// COMMISSION_FAILED. The reviewer must still confirm this behaviour.
/// </summary>
public sealed class SqlDebitGateway(Db db) : DebitGateway
{
    public int Debit(string? cuenta, string? tipoCuenta, decimal? valor, string? referencia)
    {
        if (cuenta is null || tipoCuenta is null || valor is null || valor.Value < 0m)
        {
            throw new InvalidOperationException("Invalid debit request.");
        }

        const string sql =
            "UPDATE ct_cuenta SET cta_saldo = cta_saldo - @valor " +
            "WHERE cta_numero = @cuenta AND cta_tipo = @tipo AND cta_saldo >= @valor";

        using var command = db.Command(sql);
        command.Parameters.AddWithValue("@valor", (object?)valor ?? DBNull.Value);
        command.Parameters.AddWithValue("@cuenta", (object?)cuenta ?? DBNull.Value);
        command.Parameters.AddWithValue("@tipo", (object?)tipoCuenta ?? DBNull.Value);

        var affected = command.ExecuteNonQuery();
        if (affected != 1)
        {
            // Unknown account or insufficient balance: the debit cannot be done.
            throw new InvalidOperationException("The debit could not be applied to the account.");
        }

        // There is no movement table in the target schema, so the sequence is a fixed value.
        return 1;
